"""Compose checked Core frontend and direct RF2 WASM encoder; native result has no interpreter dependency."""
from pathlib import Path
import os,subprocess,sys,hashlib,json
R=Path(__file__).resolve().parents[1];out=Path(sys.argv[1]).resolve();out.mkdir(parents=True,exist_ok=False);names=['native/rf2.rf2','native/core.rf2','native/attendance.rf2','native/attendance-kernel.rf2','native/fingerprint.rf2','native/invoice.rf2','native/invoice-kernel.rf2','native/prepared.rf2','native/workspace.rf2','native/editor.rf2','native/wasm/backend.rf2'];text='\n'.join((R/n).read_text()for n in names).replace('fn main(argc, argv)','fn legacy_main(argc, argv)');text+='\nfn main(argc,argv)\n return wasm_main(argc,argv)\nend\n';source=out/'wasm-compiler.rf2';source.write_text(text);c=Path(os.environ.get('RF2_TEST_COMPILER',R/'output/foundation-0.19-qualified/rf2c-self'));subprocess.run([c,source,out/'rf2-wasm','--opt'],check=True);subprocess.run(['/usr/bin/codesign','-s','-',out/'rf2-wasm'],check=True);(out/'BUILD.json').write_text(json.dumps({'compilerSHA256':hashlib.sha256(c.read_bytes()).hexdigest(),'binarySHA256':hashlib.sha256((out/'rf2-wasm').read_bytes()).hexdigest(),'sources':{n:hashlib.sha256((R/n).read_bytes()).hexdigest()for n in names},'target':'WASM1 bounded Core, no OS imports or WASI; emitted by native RF2'},indent=2)+'\n')
